/* CSS Custom Properties */
:root {
    --color-primary: #1a1a1a;
    --color-secondary: #f5f5f5;
    --color-accent: #d4af37;
    --color-error: #dc3545;
    --color-success: #28a745;
    --color-text: #333333;
    --color-text-light: #666666;
    --color-border: #e0e0e0;
    --color-bg: #ffffff;

    --spacing-xs: 0.5rem;
    --spacing-sm: 1rem;
    --spacing-md: 1.5rem;
    --spacing-lg: 2rem;
    --spacing-xl: 3rem;
    --spacing-2xl: 4rem;

    --font-sans: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', Arial, sans-serif;
    --font-size-sm: 0.875rem;
    --font-size-base: 1rem;
    --font-size-lg: 1.25rem;
    --font-size-xl: 1.5rem;
    --font-size-2xl: 2rem;

    --radius-sm: 4px;
    --radius-md: 8px;
    --radius-lg: 12px;

    --shadow-sm: 0 1px 2px rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px rgba(0, 0, 0, 0.1);

    --transition: all 300ms ease;
}

/* Reset & Base Styles */
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

html {
    scroll-behavior: smooth;
}

body {
    font-family: var(--font-sans);
    font-size: var(--font-size-base);
    line-height: 1.6;
    color: var(--color-text);
    background-color: var(--color-bg);
}

img {
    max-width: 100%;
    height: auto;
}

a {
    color: var(--color-primary);
    text-decoration: none;
    transition: var(--transition);
}

button {
    font-family: var(--font-sans);
    cursor: pointer;
    border: none;
    background: none;
    transition: var(--transition);
}

/* Utilities */
.container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 0 var(--spacing-md);
}

.sr-only {
    position: absolute;
    width: 1px;
    height: 1px;
    padding: 0;
    margin: -1px;
    overflow: hidden;
    clip: rect(0, 0, 0, 0);
    white-space: nowrap;
    border-width: 0;
}

/* Header */
.header {
    background-color: var(--color-bg);
    border-bottom: 1px solid var(--color-border);
    position: sticky;
    top: 0;
    z-index: 100;
    box-shadow: var(--shadow-sm);
}

.header-content {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: var(--spacing-md) 0;
}

.logo h1 {
    font-size: var(--font-size-xl);
    font-weight: 700;
    letter-spacing: -0.5px;
}

.main-nav {
    flex: 1;
    margin-left: var(--spacing-xl);
}

.nav-menu {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.nav-menu a {
    font-weight: 500;
    color: var(--color-text);
    position: relative;
}

.nav-menu a::after {
    content: '';
    position: absolute;
    bottom: -4px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: var(--color-accent);
    transition: width 300ms ease;
}

.nav-menu a:hover::after,
.nav-menu a:focus::after {
    width: 100%;
}

.nav-toggle {
    display: none;
    flex-direction: column;
    gap: 6px;
}

.nav-toggle span {
    width: 24px;
    height: 2px;
    background-color: var(--color-primary);
    border-radius: var(--radius-sm);
    transition: var(--transition);
}

.nav-toggle[aria-expanded="true"] span:nth-child(1) {
    transform: rotate(45deg) translate(8px, 8px);
}

.nav-toggle[aria-expanded="true"] span:nth-child(2) {
    opacity: 0;
}

.nav-toggle[aria-expanded="true"] span:nth-child(3) {
    transform: rotate(-45deg) translate(7px, -7px);
}

.header-actions {
    display: flex;
    gap: var(--spacing-md);
    align-items: center;
}

.search-btn,
.cart-btn {
    width: 40px;
    height: 40px;
    display: flex;
    align-items: center;
    justify-content: center;
    border-radius: var(--radius-md);
    color: var(--color-primary);
}

.search-btn:hover,
.cart-btn:hover,
.search-btn:focus,
.cart-btn:focus {
    background-color: var(--color-secondary);
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.search-btn svg,
.cart-btn svg {
    width: 20px;
    height: 20px;
}

.cart-btn {
    position: relative;
}

.cart-count {
    position: absolute;
    top: -8px;
    right: -8px;
    background-color: var(--color-error);
    color: white;
    width: 20px;
    height: 20px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: var(--font-size-sm);
    font-weight: 700;
}

/* Hero Section */
.hero {
    background: linear-gradient(135deg, var(--color-primary) 0%, #2a2a2a 100%);
    color: white;
    padding: var(--spacing-2xl) var(--spacing-md);
    text-align: center;
    min-height: 400px;
    display: flex;
    align-items: center;
    justify-content: center;
}

.hero-content h2 {
    font-size: var(--font-size-2xl);
    margin-bottom: var(--spacing-md);
    font-weight: 700;
}

.hero-content p {
    font-size: var(--font-size-lg);
    margin-bottom: var(--spacing-lg);
    opacity: 0.9;
}

.cta-button {
    background-color: var(--color-accent);
    color: var(--color-primary);
    padding: var(--spacing-sm) var(--spacing-lg);
    border-radius: var(--radius-md);
    font-weight: 600;
    font-size: var(--font-size-base);
    box-shadow: var(--shadow-md);
}

.cta-button:hover,
.cta-button:focus {
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
    outline: 2px solid white;
    outline-offset: 2px;
}

/* Sections */
section {
    padding: var(--spacing-2xl) var(--spacing-md);
}

section h2 {
    font-size: var(--font-size-2xl);
    margin-bottom: var(--spacing-xl);
    font-weight: 700;
}

/* Products Section */
.products-section {
    background-color: var(--color-bg);
}

.products-grid {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(250px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.product-card {
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.product-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.product-card:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.product-image {
    width: 100%;
    height: 250px;
    background: linear-gradient(135deg, #f5f5f5 0%, #e8e8e8 100%);
    overflow: hidden;
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: var(--font-size-sm);
    color: var(--color-text-light);
}

.product-info {
    padding: var(--spacing-md);
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.product-name {
    font-size: var(--font-size-base);
    font-weight: 600;
    margin-bottom: var(--spacing-xs);
    color: var(--color-primary);
}

.product-description {
    font-size: var(--font-size-sm);
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
}

.product-price {
    font-size: var(--font-size-lg);
    font-weight: 700;
    color: var(--color-accent);
    margin-bottom: var(--spacing-md);
}

.add-to-cart {
    background-color: var(--color-primary);
    color: white;
    padding: var(--spacing-sm);
    border-radius: var(--radius-md);
    font-weight: 600;
    width: 100%;
}

.add-to-cart:hover,
.add-to-cart:focus {
    background-color: #333;
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Deals Section */
.deals-section {
    background-color: var(--color-secondary);
}

.deals-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.deal-card {
    background-color: var(--color-bg);
    border-radius: var(--radius-lg);
    padding: var(--spacing-lg);
    box-shadow: var(--shadow-sm);
    transition: var(--transition);
    position: relative;
    overflow: hidden;
}

.deal-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.deal-card:focus-within {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.deal-badge {
    position: absolute;
    top: var(--spacing-md);
    right: var(--spacing-md);
    background-color: var(--color-error);
    color: white;
    padding: var(--spacing-xs) var(--spacing-md);
    border-radius: var(--radius-md);
    font-weight: 700;
    font-size: var(--font-size-sm);
}

.deal-title {
    font-size: var(--font-size-lg);
    font-weight: 700;
    margin-bottom: var(--spacing-md);
    color: var(--color-primary);
}

.deal-description {
    font-size: var(--font-size-sm);
    color: var(--color-text-light);
    margin-bottom: var(--spacing-lg);
    line-height: 1.8;
}

.deal-link {
    display: inline-block;
    color: var(--color-accent);
    font-weight: 600;
    position: relative;
}

.deal-link::after {
    content: '→';
    margin-left: var(--spacing-xs);
    transition: var(--transition);
}

.deal-link:hover::after,
.deal-link:focus::after {
    transform: translateX(4px);
}

.deal-link:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Editorial Section */
.editorial-section {
    background-color: var(--color-bg);
}

.editorial-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(320px, 1fr));
    gap: var(--spacing-lg);
    list-style: none;
}

.editorial-card {
    border-radius: var(--radius-lg);
    overflow: hidden;
    box-shadow: var(--shadow-sm);
    transition: var(--transition);
    display: flex;
    flex-direction: column;
}

.editorial-card:hover {
    box-shadow: var(--shadow-lg);
    transform: translateY(-4px);
}

.editorial-image {
    width: 100%;
    height: 200px;
    background: linear-gradient(135deg, #f5f5f5 0%, #e8e8e8 100%);
    display: flex;
    align-items: center;
    justify-content: center;
    font-size: var(--font-size-sm);
    color: var(--color-text-light);
}

.editorial-content {
    padding: var(--spacing-lg);
    flex-grow: 1;
    display: flex;
    flex-direction: column;
}

.editorial-category {
    font-size: var(--font-size-sm);
    color: var(--color-accent);
    font-weight: 600;
    text-transform: uppercase;
    letter-spacing: 0.5px;
    margin-bottom: var(--spacing-xs);
}

.editorial-title {
    font-size: var(--font-size-lg);
    font-weight: 700;
    margin-bottom: var(--spacing-sm);
    color: var(--color-primary);
}

.editorial-excerpt {
    font-size: var(--font-size-sm);
    color: var(--color-text-light);
    margin-bottom: var(--spacing-md);
    flex-grow: 1;
    line-height: 1.8;
}

.read-more {
    color: var(--color-primary);
    font-weight: 600;
    display: inline-block;
    position: relative;
}

.read-more::after {
    content: '→';
    margin-left: var(--spacing-xs);
    transition: var(--transition);
}

.read-more:hover::after,
.read-more:focus::after {
    transform: translateX(4px);
}

.read-more:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

/* Newsletter Section */
.newsletter-section {
    background: linear-gradient(135deg, var(--color-primary) 0%, #2a2a2a 100%);
    color: white;
    padding: var(--spacing-2xl) var(--spacing-md);
}

.newsletter-content {
    text-align: center;
    max-width: 600px;
    margin: 0 auto;
}

.newsletter-content h2 {
    font-size: var(--font-size-2xl);
    margin-bottom: var(--spacing-md);
}

.newsletter-content p {
    font-size: var(--font-size-base);
    opacity: 0.9;
    margin-bottom: var(--spacing-lg);
}

.newsletter-form {
    display: flex;
    gap: var(--spacing-sm);
    flex-wrap: wrap;
    justify-content: center;
}

.newsletter-form input {
    flex: 1;
    min-width: 250px;
    padding: var(--spacing-sm) var(--spacing-md);
    border: none;
    border-radius: var(--radius-md);
    font-size: var(--font-size-base);
    background-color: white;
    color: var(--color-primary);
}

.newsletter-form input::placeholder {
    color: var(--color-text-light);
}

.newsletter-form input:focus {
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.submit-btn {
    background-color: var(--color-accent);
    color: var(--color-primary);
    padding: var(--spacing-sm) var(--spacing-lg);
    border-radius: var(--radius-md);
    font-weight: 600;
    white-space: nowrap;
}

.submit-btn:hover,
.submit-btn:focus {
    transform: translateY(-2px);
    box-shadow: var(--shadow-lg);
    outline: 2px solid white;
    outline-offset: 2px;
}

/* Footer */
.footer {
    background-color: var(--color-primary);
    color: white;
    padding: var(--spacing-2xl) var(--spacing-md);
}

.footer-grid {
    display: grid;
    grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
    gap: var(--spacing-xl);
    margin-bottom: var(--spacing-2xl);
}

.footer-section h3 {
    font-size: var(--font-size-base);
    margin-bottom: var(--spacing-md);
    font-weight: 700;
}

.footer-section p {
    font-size: var(--font-size-sm);
    opacity: 0.8;
    line-height: 1.8;
}

.footer-section ul {
    list-style: none;
}

.footer-section li {
    margin-bottom: var(--spacing-sm);
}

.footer-section a {
    color: white;
    font-size: var(--font-size-sm);
    opacity: 0.8;
}

.footer-section a:hover,
.footer-section a:focus {
    opacity: 1;
    color: var(--color-accent);
    outline: 2px solid var(--color-accent);
    outline-offset: 2px;
}

.social-links {
    display: flex;
    gap: var(--spacing-md);
}

.footer-bottom {
    border-top: 1px solid rgba(255, 255, 255, 0.1);
    padding-top: var(--spacing-lg);
    display: flex;
    justify-content: space-between;
    align-items: center;
    flex-wrap: wrap;
    gap: var(--spacing-md);
}

.footer-bottom p {
    font-size: var(--font-size-sm);
    opacity: 0.8;
}

.footer-links {
    display: flex;
    list-style: none;
    gap: var(--spacing-lg);
}

.footer-links a {
    font-size: var(--font-size-sm);
    opacity: 0.8;
}

/* Responsive Design */
@media (max-width: 768px) {
    .main-nav {
        display: none;
        position: absolute;
        top: 100%;
        left: 0;
        right: 0;
        background-color: var(--color-bg);
        border-bottom: 1px solid var(--color-border);
        padding: var(--spacing-md);
        margin-left: 0;
    }

    .main-nav.active {
        display: block;
    }

    .nav-menu {
        flex-direction: column;
        gap: var(--spacing-md);
    }

    .nav-toggle {
        display: flex;
    }

    .hero-content h2 {
        font-size: var(--font-size-xl);
    }

    .products-grid,
    .deals-grid,
    .editorial-grid {
        grid-template-columns: repeat(auto-fill, minmax(200px, 1fr));
    }

    .newsletter-form {
        flex-direction: column;
    }

