}

// Handle Add to Cart
function handleAddToCart(e) {
    const btn = e.target;
    const productId = btn.dataset.productId;
    const productName = btn.dataset.productName;

    cartItems++;
    updateCartCount();

    // Visual feedback
    const originalText = btn.textContent;
    btn.textContent = '✓ Added!';
    btn.style.backgroundColor = '#28a745';

    setTimeout(() => {
        btn.textContent = originalText;
        btn.style.backgroundColor = '';
    }, 1500);

    // Announce to screen readers
    announceToScreenReader(`${productName} added to cart`);
}

// Update Cart Count
function updateCartCount() {
    cartCount.textContent = cartItems;
    localStorage.setItem('cartItems', cartItems);
}

// Load Cart Count from localStorage
function loadCartCount() {
    const saved = localStorage.getItem('cartItems');
    if (saved) {
        cartItems = parseInt(saved);
        cartCount.textContent = cartItems;
    }
}

// Announce to screen readers
function announceToScreenReader(message) {
    const announcement = document.createElement('div');
    announcement.setAttribute('role', 'status');
    announcement.setAttribute('aria-live', 'polite');
    announcement.className = 'sr-only';
    announcement.textContent = message;
    document.body.appendChild(announcement);

    setTimeout(() => {
        announcement.remove();
    }, 1000);
}

// Setup Event Listeners
function setupEventListeners() {
    // Mobile menu toggle
    navToggle.addEventListener('click', toggleMobileMenu);

    // Close menu when clicking on nav links
    document.querySelectorAll('.nav-menu a').forEach(link => {
        link.addEventListener('click', closeMobileMenu);
    });

    // Cart button click
    cartBtn.addEventListener('click', handleCartClick);

    // Newsletter form
    newsletterForm.addEventListener('submit', handleNewsletterSubmit);

    // CTA button
    ctaButton.addEventListener('click', () => {
        document.querySelector('#products').scrollIntoView({ behavior: 'smooth' });
    });

    // Close menu when clicking outside
    document.addEventListener('click', (e) => {
        if (!e.target.closest('.main-nav') && !e.target.closest('.nav-toggle')) {
            closeMobileMenu();
        }
    });

    // Keyboard navigation
    document.addEventListener('keydown', (e) => {
        if (e.key === 'Escape') {
            closeMobileMenu();
        }
    });
}

// Toggle Mobile Menu
function toggleMobileMenu() {
    const isExpanded = navToggle.getAttribute('aria-expanded') === 'true';
    navToggle.setAttribute('aria-expanded', !isExpanded);
    navMenu.classList.toggle('active');
}

// Close Mobile Menu
function closeMobileMenu() {
    navToggle.setAttribute('aria-expanded', false);
    navMenu.classList.remove('active');
}

// Handle Cart Click
function handleCartClick() {
    announceToScreenReader(`Shopping cart contains ${cartItems} items`);
    // In a real app, this would navigate to the cart page
    console.log('Cart clicked - total items:', cartItems);
}

// Handle Newsletter Submit
function handleNewsletterSubmit(e) {
    e.preventDefault();
    const emailInput = document.querySelector('#email-input');
    const email = emailInput.value;

    if (email) {
        // Show success message
        const form = e.target;
        const originalHTML = form.innerHTML;

        form.innerHTML = '<p style="color: var(--color-accent); font-weight: 600;">✓ Successfully subscribed!</p>';

        setTimeout(() => {
            form.innerHTML = originalHTML;
            emailInput.value = '';
        }, 2000);

        announceToScreenReader('Successfully subscribed to newsletter');
    }
}

// Smooth scroll for anchor links
document.querySelectorAll('a[href^="#"]').forEach(anchor => {
    anchor.addEventListener('click', function (e) {
        const href = this.getAttribute('href');
        if (href !== '#' && document.querySelector(href)) {
            e.preventDefault();
            document.querySelector(href).scrollIntoView({
                behavior: 'smooth',
                block: 'start'
            });
        }
    });
});

// Add keyboard focus visibility
document.addEventListener('keydown', (e) => {
    if (e.key === 'Tab') {
        document.body.classList.add('keyboard-nav');
    }
});

document.addEventListener('mousedown', () => {
    document.body.classList.remove('keyboard-nav');
});

